-- Isolated harness only. Exact live policy expressions, whitespace normalized.
CREATE POLICY "Financeiro read partner_orders" ON partner_orders FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'financeiro'));
CREATE POLICY b2b_phase1_tenant_guard ON partner_orders AS RESTRICTIVE FOR ALL TO authenticated USING(platform_private.b2b_phase1_partner_visible(partner_id,false)) WITH CHECK(platform_private.b2b_phase1_partner_visible(partner_id,false));
CREATE POLICY partner_orders_select ON partner_orders FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial') OR (platform_private.has_role(auth.uid(),'parceiro_b2b') AND partner_id=get_user_partner_id()));
CREATE POLICY partner_orders_insert ON partner_orders FOR INSERT TO authenticated WITH CHECK(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY partner_orders_update ON partner_orders FOR UPDATE TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial')) WITH CHECK(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY msg_admin_select ON partner_order_messages FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY msg_admin_insert ON partner_order_messages FOR INSERT TO authenticated WITH CHECK((platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial')) AND autor_tipo=ANY(ARRAY['comercial'::order_message_author,'admin'::order_message_author]));
CREATE POLICY msg_partner_select ON partner_order_messages FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'parceiro_b2b') AND EXISTS(SELECT 1 FROM partner_orders po WHERE po.id=partner_order_messages.order_id AND po.partner_id=get_user_partner_id()));
CREATE POLICY msg_partner_insert ON partner_order_messages FOR INSERT TO authenticated WITH CHECK(platform_private.has_role(auth.uid(),'parceiro_b2b') AND autor_tipo='parceiro' AND EXISTS(SELECT 1 FROM partner_orders po WHERE po.id=partner_order_messages.order_id AND po.partner_id=get_user_partner_id()));
CREATE POLICY poma_select ON partner_order_message_attachments FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial') OR EXISTS(SELECT 1 FROM partner_order_messages m JOIN partner_orders po ON po.id=m.order_id WHERE m.id=partner_order_message_attachments.message_id AND platform_private.has_role(auth.uid(),'parceiro_b2b') AND po.partner_id=get_user_partner_id()));
CREATE POLICY poma_insert ON partner_order_message_attachments FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND EXISTS(SELECT 1 FROM partner_order_messages m JOIN partner_orders po ON po.id=m.order_id WHERE m.id=partner_order_message_attachments.message_id AND (platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial') OR (platform_private.has_role(auth.uid(),'parceiro_b2b') AND po.partner_id=get_user_partner_id()))));
CREATE POLICY poma_delete ON partner_order_message_attachments FOR DELETE TO authenticated USING(uploaded_by=auth.uid() OR platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY b2b_direct_partner_row_containment ON partner_accounts AS RESTRICTIVE FOR ALL TO authenticated USING(platform_private.b2b_direct_partner_row_allowed()) WITH CHECK(platform_private.b2b_direct_partner_row_allowed());
CREATE POLICY d51_5_partner_accounts_tenant_guard ON partner_accounts AS RESTRICTIVE FOR ALL TO authenticated
USING(platform_private.b2b_coherent_self_partner(id) OR (commercial_owner_organization_id=h15_actor_organization() AND (client_id IS NULL OR EXISTS(SELECT 1 FROM clientes c WHERE c.id=partner_accounts.client_id AND c.organization_id=partner_accounts.commercial_owner_organization_id))) OR (commercial_owner_organization_id IS NULL AND EXISTS(SELECT 1 FROM clientes c WHERE c.id=partner_accounts.client_id AND c.organization_id=h15_actor_organization())))
WITH CHECK(commercial_owner_organization_id=h15_actor_organization() AND (client_id IS NULL OR EXISTS(SELECT 1 FROM clientes c WHERE c.id=partner_accounts.client_id AND c.organization_id=partner_accounts.commercial_owner_organization_id)));
CREATE POLICY partner_accounts_select ON partner_accounts FOR SELECT TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY partner_accounts_self_select ON partner_accounts FOR SELECT TO public USING(platform_private.b2b_coherent_self_partner(id));
CREATE POLICY partner_accounts_insert ON partner_accounts FOR INSERT TO authenticated WITH CHECK(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));
CREATE POLICY partner_accounts_update ON partner_accounts FOR UPDATE TO authenticated USING(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial')) WITH CHECK(platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor_comercial'));